helpers=r'''function ensureActivities(){if(!Array.isArray(S.activities))S.activities=[];if(!S.set)S.set={newN:30,reviewN:80,rate:.92};if(!Array.isArray(S.set.todayBooks))S.set.todayBooks=[];if(!Array.isArray(S.set.typeBooks))S.set.typeBooks=[]}
function allBooks(){var a=[];S.words.forEach(function(w){(w.src||[]).forEach(function(b){if(a.indexOf(b)<0)a.push(b)})});return a.sort()}
function wordsInBooks(books){books=books||[];return S.words.filter(function(w){return!w.ret&&(!books.length||(w.src||[]).some(function(b){return books.indexOf(b)>=0}))})}
function scopeWordIds(books){return new Set(wordsInBooks(books).map(function(w){return w.id}))}
function selectedBooks(scope){ensureActivities();return scope==='type'?S.set.typeBooks:S.set.todayBooks}
function bookPicker(scope){var selected=selectedBooks(scope),books=allBooks();return'<div class="bookPicker"><button class="bookChip '+(!selected.length?'on':'')+'" data-pick-scope="'+scope+'" data-pick-book="__all__">全部词书</button>'+books.map(function(b){return'<button class="bookChip '+(selected.indexOf(b)>=0?'on':'')+'" data-pick-scope="'+scope+'" data-pick-book="'+esc(b)+'">'+esc(b)+'</button>'}).join('')+'</div>'}
function bindBookPicker(scope,rerender){document.querySelectorAll('[data-pick-scope="'+scope+'"]').forEach(function(b){b.onclick=function(){var key=scope==='type'?'typeBooks':'todayBooks',name=this.dataset.pickBook;if(name==='__all__'){S.set[key]=[]}else{var a=S.set[key]||[],i=a.indexOf(name);if(i>=0)a.splice(i,1);else a.push(name);S.set[key]=a}save();rerender()}})}
function firstEverTs(wordId){var a=S.events.filter(function(e){return e.wordId===wordId}).sort(function(a,b){return a.ts-b.ts});return a.length?a[0].ts:0}
function todayScopeData(books){var ids=scopeWordIds(books),d=day(),todayEvents=S.events.filter(function(e){return e.date===d&&ids.has(e.wordId)}),wordIds=[...new Set(todayEvents.map(function(e){return e.wordId}))],newIds=[],reviewIds=[];wordIds.forEach(function(idv){var first=firstEverTs(idv);if(first&&new Date(first).toLocaleDateString('sv-SE')===d)newIds.push(idv);else reviewIds.push(idv)});var firsts=[];wordIds.forEach(function(idv){var a=todayEvents.filter(function(e){return e.wordId===idv}).sort(function(a,b){return a.ts-b.ts});if(a[0])firsts.push(a[0])});return{events:todayEvents,newIds:newIds,reviewIds:reviewIds,firstGood:firsts.filter(function(e){return e.res==='good'}).length,firstBad:firsts.filter(function(e){return e.res==='bad'}).length,typed:new Set(todayEvents.filter(function(e){return e.mode==='type'}).map(function(e){return e.wordId})).size}}
function startActivity(mode,books,label){ensureActivities();var a={id:id(),mode:mode,books:(books||[]).slice(),label:label||'',date:day(),start:Date.now(),end:Date.now()};S.activities.push(a);save();return a.id}
function touchActivity(aid){ensureActivities();var a=S.activities.find(function(x){return x.id===aid});if(a){a.end=Date.now();save()}}
function endActivity(aid){touchActivity(aid)}
function activityMinutes(mode,books){ensureActivities();var d=day(),a=S.activities.filter(function(x){if(x.date!==d||x.mode!==mode)return false;if(!books||!books.length)return true;if(!x.books||!x.books.length)return true;return x.books.some(function(b){return books.indexOf(b)>=0})}),ms=a.reduce(function(n,x){return n+Math.max(0,(x.end||x.start)-x.start)},0);if(ms>0)return Math.max(1,Math.round(ms/60000));var ids=scopeWordIds(books||[]),evs=S.events.filter(function(e){return e.date===d&&e.mode===mode&&ids.has(e.wordId)}).sort(function(a,b){return a.ts-b.ts});if(!evs.length)return 0;var est=12000;for(var i=1;i<evs.length;i++){var gap=evs[i].ts-evs[i-1].ts;est+=gap<300000?Math.min(gap,60000):12000}return Math.max(1,Math.round(est/60000))}
function dueAndFresh(books){var pool=wordsInBooks(books),seen=new Set(S.events.map(function(e){return e.wordId})),now=Date.now();return{pool:pool,due:pool.filter(function(w){return seen.has(w.id)&&(w.next||0)<=now}),fresh:pool.filter(function(w){return!seen.has(w.id)})}}
'''
