home_today=r'''function home(){ensureActivities();var total=S.words.filter(function(w){return!w.ret}).length,today=todayScopeData([]),mins=activityMinutes('listen',[])+activityMinutes('type',[]),texts=Array.isArray(S.texts)?S.texts.length:0;$('home').innerHTML='<div class="card dashboardHero"><h2>听词</h2><p>首页只放入口和总览。具体的新词、复习、词书范围和今日记录都放到「今日」里。</p><div class="todayStats" style="margin-top:16px"><div class="todayStat"><b>'+total+'</b><span>词库总词数</span></div><div class="todayStat"><b>'+today.newIds.length+'</b><span>今日新学</span></div><div class="todayStat"><b>'+today.reviewIds.length+'</b><span>今日复习</span></div><div class="todayStat"><b>'+mins+'m</b><span>今日学习时间</span></div></div></div><div class="homeEntryGrid"><button class="homeEntry" id="homeToday"><b>今日学习</b><span>选词书，看今天的新词/复习计划，再开始听音。</span></button><button class="homeEntry" id="homeType"><b>手打强化</b><span>按词书和历史不熟记录做更强的主动提取。</span></button><button class="homeEntry" id="homeText"><b>文本库</b><span>'+texts+' 篇已保存文本，逐句听、循环、隐藏原文。</span></button><button class="homeEntry" id="homeStats"><b>学习统计</b><span>首轮熟悉率、困难词、日历和未来复习量。</span></button></div>';$('homeToday').onclick=function(){go('today')};$('homeType').onclick=function(){go('type')};$('homeText').onclick=function(){go('text')};$('homeStats').onclick=function(){go('stats')}}
function todayView(){ensureActivities();var books=selectedBooks('today'),df=dueAndFresh(books),td=todayScopeData(books),mins=activityMinutes('listen',books),bookList=books.length?books:allBooks();$('today').innerHTML='<div class="card"><div class="textHead"><div><h2 style="margin:0 0 5px">今日学习</h2><div class="small">先选今天要学的词书；可多选，重复词只出现一次。</div></div><span class="collectionBadge">'+(books.length?books.length+' 本':'全部')+'</span></div>'+bookPicker('today')+'</div><div class="todayStats" style="margin-top:14px"><div class="todayStat"><b>'+td.newIds.length+'</b><span>今日已学新词</span></div><div class="todayStat"><b>'+td.reviewIds.length+'</b><span>今日已复习</span></div><div class="todayStat"><b>'+td.firstGood+'</b><span>首轮熟悉</span></div><div class="todayStat"><b>'+mins+'m</b><span>听音用时</span></div></div><div class="card" style="margin-top:14px"><div class="heatTitle"><div><b>今天的学习计划</b><div class="small">计划数量可以随时改；实际只从上面选中的词书里抽。</div></div></div><div class="planGrid"><div class="planBox"><div class="small">新词</div><div class="big">'+S.set.newN+'</div><div class="sub">当前范围还有 '+df.fresh.length+' 个未学</div></div><div class="planBox"><div class="small">复习</div><div class="big">'+S.set.reviewN+'</div><div class="sub">当前到期 '+df.due.length+' 个</div></div></div><div class="planControls"><div class="field"><label>本轮新词</label><input id="todayNewN" type="number" min="0" value="'+S.set.newN+'"></div><div class="field"><label>本轮复习</label><input id="todayRevN" type="number" min="0" value="'+S.set.reviewN+'"></div></div><div class="row" style="margin-top:16px"><button id="todayStart" class="primary">开始今日听音</button><span class="small">预计本轮 '+Math.min(S.set.newN,df.fresh.length)+' 新词 + '+Math.min(S.set.reviewN,df.due.length)+' 复习</span></div></div><div class="card" style="margin-top:14px"><div><b>各词书今天的情况</b><div class="small">熟悉/不熟悉仍然是一套共享状态，词书这里只负责来源和筛选。</div></div><div class="bookDailyList">'+(bookList.length?bookList.map(function(b){var x=todayScopeData([b]),count=wordsInBooks([b]).length;return'<div class="bookDailyRow"><div class="bookDailyTop"><b>'+esc(b)+'</b><span class="small">'+count+' 词</span></div><div class="bookDailyNums"><div class="bookDailyNum"><strong>'+x.newIds.length+'</strong>今日新词</div><div class="bookDailyNum"><strong>'+x.reviewIds.length+'</strong>今日复习</div><div class="bookDailyNum"><strong class="ok">'+x.firstGood+'</strong>首轮熟悉</div><div class="bookDailyNum"><strong class="miss">'+x.firstBad+'</strong>首轮不熟</div></div></div>'}).join(''):'<div class="small">还没有词书，先去词库导入。</div>')+'</div></div>';bindBookPicker('today',todayView);$('todayNewN').onchange=function(){S.set.newN=Math.max(0,+this.value||0);save();todayView()};$('todayRevN').onchange=function(){S.set.reviewN=Math.max(0,+this.value||0);save();todayView()};$('todayStart').onclick=start}
'''
