start_new=r'''function start(){ensureActivities();var books=selectedBooks('today'),df=dueAndFresh(books),r=df.due.slice(),f=df.fresh.slice();r.sort(function(a,b){return(b.diff||0)-(a.diff||0)||(a.next||0)-(b.next||0)});f.sort(function(a,b){return(b.src.length-a.src.length)});var q=r.slice(0,S.set.reviewN).concat(f.slice(0,S.set.newN));if(!q.length){toast('当前词书范围今天没有待学习词');return}sess={q:q,i:0,show:false,res:null,books:books.slice(),activityId:startActivity('listen',books,'今日听音')};document.body.classList.add('focusStudy');cur='study';document.querySelectorAll('.view').forEach(function(x){x.classList.remove('on')});$('study').classList.add('on');$('ey').textContent='听音';$('title').textContent='今日学习';nav();study();if(q[0])setTimeout(function(){speak(q[0].en)},60)}function cw()'''
s=s[:m.start()]+home_today+start_new+s[m.end():]

# Study answer: show source books and return to Today page.
