new_type=r'''function typeSelectedBooks(){ensureActivities();return S.set.typeBooks||[]}
function typePresetCount(kind){var bs=typeSelectedBooks();if(kind==='auto')return typeQueue({kind:'auto',books:bs,limit:0}).length;if(kind==='todayListen')return typeQueue({kind:'filter',date:day(),mode:'listen',books:bs,min:1,limit:0}).length;if(kind==='todayType')return typeQueue({kind:'filter',date:day(),mode:'type',books:bs,min:1,limit:0}).length;if(kind==='repeat7')return typeQueue({kind:'repeat7',from:typeDayOffset(-6),mode:'all',books:bs,limit:0}).length;return 0}
function startTypeQueue(q,label){if(!q.length){toast('这组暂时没有待强化词');return}var bs=typeSelectedBooks();document.body.classList.add('focusType');ts={active:true,q:q,i:0,show:false,res:null,input:'',label:label||'手打强化',done:[],skipped:0,books:bs.slice(),activityId:startActivity('type',bs,label||'手打强化')};typeCard();setTimeout(function(){if(q[0])speak(q[0].en)},60)}
function typeLanding(){ensureActivities();if(ts&&ts.active)return typeCard();document.body.classList.remove('focusType');var bs=typeSelectedBooks(),cAuto=typePresetCount('auto'),cListen=typePresetCount('todayListen'),cType=typePresetCount('todayType'),cRepeat=typePresetCount('repeat7'),scopeToday=todayScopeData(bs),typedToday=new Set(S.events.filter(function(e){return e.date===day()&&e.mode==='type'&&scopeWordIds(bs).has(e.wordId)}).map(function(e){return e.wordId})).size,tmins=activityMinutes('type',bs);$('type').innerHTML='<div class="card handScope"><div class="handScopeTop"><div><b style="font-size:20px">手打词书范围</b><div class="small">快捷推荐和自定义筛选都会只从这里选中的词书取词。</div></div><span class="collectionBadge">'+(bs.length?bs.length+' 本':'全部')+'</span></div>'+bookPicker('type')+'<div class="todayStats" style="margin-top:14px"><div class="todayStat"><b>'+scopeToday.newIds.length+'</b><span>今日听音新词</span></div><div class="todayStat"><b>'+scopeToday.reviewIds.length+'</b><span>今日听音复习</span></div><div class="todayStat"><b>'+typedToday+'</b><span>今日手打词</span></div><div class="todayStat"><b>'+tmins+'m</b><span>手打用时</span></div></div></div><div class="card handHero"><h2>手打强化</h2><p>优先练真正卡住过的词。所有入口都会遵循上面的词书范围。</p><div class="quickGrid"><button class="quickCard" data-quick="auto"><span class="qnum">'+cAuto+'</span><b>自动推荐</b><div class="small">跨天不熟权重最高，兼顾近期反复卡住</div></button><button class="quickCard" data-quick="todayListen"><span class="qnum">'+cListen+'</span><b>今日听音不熟</b><div class="small">今天听音时标过不熟的词</div></button><button class="quickCard" data-quick="todayType"><span class="qnum">'+cType+'</span><b>今日手打不熟</b><div class="small">今天手打后仍然不稳的词</div></button><button class="quickCard" data-quick="repeat7"><span class="qnum">'+cRepeat+'</span><b>近 7 天反复不熟</b><div class="small">近期重复失败的词</div></button></div></div><div class="card handFilter"><div class="heatTitle"><div><b>自定义一组</b><div class="small">在上面词书范围内，再按日期和不熟次数筛。</div></div></div><div class="filterGrid" style="margin-top:14px"><div class="field"><label>日期</label><input id="td" type="date" value="'+day()+'"></div><div class="field"><label>不熟来自哪里</label><select id="tmode"><option value="all">听音 + 手打</option><option value="listen">只看听音</option><option value="type">只看手打</option></select></div><div class="field"><label>至少标记不熟</label><select id="tm"><option value="1">1 次</option><option value="2">2 次</option><option value="3">3 次</option><option value="5">5 次</option></select></div><div class="field"><label>本轮数量</label><select id="tlimit"><option value="20">20 个</option><option value="50" selected>50 个</option><option value="100">100 个</option><option value="0">全部</option></select></div></div><div id="tpreview"></div></div>';bindBookPicker('type',typeLanding);function quick(kind){var q,label,books=typeSelectedBooks();if(kind==='auto'){q=typeQueue({kind:'auto',books:books,limit:30});label='自动推荐'}else if(kind==='todayListen'){q=typeQueue({kind:'filter',date:day(),mode:'listen',books:books,min:1,limit:50});label='今日听音不熟'}else if(kind==='todayType'){q=typeQueue({kind:'filter',date:day(),mode:'type',books:books,min:1,limit:50});label='今日手打不熟'}else{q=typeQueue({kind:'repeat7',from:typeDayOffset(-6),mode:'all',books:books,limit:50});label='近 7 天反复不熟'}startTypeQueue(q,label)}document.querySelectorAll('[data-quick]').forEach(function(b){b.onclick=function(){quick(this.dataset.quick)}});function preview(){var opt={kind:'filter',date:$('td').value,mode:$('tmode').value,min:+$('tm').value||1,books:typeSelectedBooks(),limit:+$('tlimit').value||0},q=typeQueue(opt),all=typeQueue(Object.assign({},opt,{limit:0}));$('tpreview').innerHTML='<div class="matchBox"><div><div class="small">匹配到</div><div class="matchNum">'+all.length+' 个词</div></div><button id="tb" class="primary" '+(!q.length?'disabled':'')+'>开始这组'+(q.length?' · '+q.length:'')+'</button></div>'+(q.length?'<div class="previewWords">'+q.slice(0,10).map(function(w){return'<span class="previewWord">'+esc(w.en)+'</span>'}).join('')+(q.length>10?'<span class="previewWord">…</span>':'')+'</div>':'<div class="small" style="margin-top:10px">这个筛选条件下暂时没有不熟词。</div>');if($('tb'))$('tb').onclick=function(){startTypeQueue(q,'自定义强化')}}['td','tmode','tm','tlimit'].forEach(function(id){$(id).onchange=preview});preview()}
function typeFinish()'''
s=s[:m2.start()]+new_type+s[m2.end():]

